-- UHY-ASK pilot: checks the CSA mapping (clients/uhy/data/csa-mapping.json) against the restored copy.
-- Read-only. Returns counts only: no names, numbers or addresses. Made from the mapping file; if the
-- mapping changes, make this file again so the two stay in step.
--   .\run-sql.ps1 -Server '.\SQLEXPRESS' -Database CSA_Copy -File .\csa-mapping-check.sql -OutDir C:\Clerk\csa-out
SET NOCOUNT ON;

SELECT 'companies' AS entity, COUNT(*) AS n, COUNT(*) - COUNT(DISTINCT q.csaId) AS duplicate_ids, SUM(CASE WHEN q.nameEn IS NULL THEN 1 ELSE 0 END) AS missing_nameEn, SUM(CASE WHEN q.incorporatedOn IS NULL THEN 1 ELSE 0 END) AS missing_incorporatedOn, SUM(CASE WHEN q.companyNumber IS NULL THEN 1 ELSE 0 END) AS missing_companyNumber, SUM(CASE WHEN q.brNumber IS NULL THEN 1 ELSE 0 END) AS missing_brNumber, SUM(CASE WHEN q.registeredOffice IS NULL THEN 1 ELSE 0 END) AS missing_registeredOffice, SUM(CASE WHEN q.fyeMonth IS NULL THEN 1 ELSE 0 END) AS missing_fyeMonth, SUM(CASE WHEN q.nameZh IS NULL THEN 1 ELSE 0 END) AS missing_nameZh FROM (SELECT LTRIM(RTRIM(c.CLIENTID)) AS csaId, LTRIM(RTRIM(c.CLIENTID)) AS code, LTRIM(RTRIM(c.NAME_1 + ' ' + ISNULL(c.NAME_2, ''))) AS nameEn, NULLIF(LTRIM(RTRIM(c.NAME_C)), '') AS nameZh, b.BUSREGNO AS brNumber, NULLIF(LTRIM(RTRIM(c.COMNUM)), '') AS companyNumber, CONVERT(char(10), c.INCDATE, 23) AS incorporatedOn, NULL AS registeredOn, CASE WHEN c.AC_DDMM LIKE '[0-9][0-9]/[0-9][0-9]' THEN CAST(RIGHT(c.AC_DDMM, 2) AS int) END AS fyeMonth, CASE WHEN c.AC_DDMM LIKE '[0-9][0-9]/[0-9][0-9]' THEN CAST(LEFT(c.AC_DDMM, 2) AS int) END AS fyeDay, STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_CE)), ''), ''), 1, 2, '') AS registeredOffice, 'private' AS companyType FROM CLIENT c OUTER APPLY (SELECT TOP 1 r.BUSREGNO FROM BUSREG r WHERE r.CLIENTID = c.CLIENTID AND r.BRTYPE = 'COR' AND r.TILLDATE IS NULL AND r.BUSREGNO LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' ORDER BY r.ISRO DESC) b WHERE c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) q;

SELECT 'officers' AS entity, COUNT(*) AS n, COUNT(*) - COUNT(DISTINCT q.csaId) AS duplicate_ids, SUM(CASE WHEN q.correspondenceAddress IS NULL THEN 1 ELSE 0 END) AS missing_correspondenceAddress, SUM(CASE WHEN q.idNumber IS NULL THEN 1 ELSE 0 END) AS missing_idNumber, SUM(CASE WHEN q.brNumber IS NULL THEN 1 ELSE 0 END) AS missing_brNumber, SUM(CASE WHEN q.tcspLicence IS NULL THEN 1 ELSE 0 END) AS missing_tcspLicence, SUM(CASE WHEN q.nameZh IS NULL THEN 1 ELSE 0 END) AS missing_nameZh, SUM(CASE WHEN q.appointedOn IS NULL THEN 1 ELSE 0 END) AS missing_appointedOn, SUM(CASE WHEN q.nameEn = 'Name not recorded in CSA' THEN 1 ELSE 0 END) AS no_name_in_csa FROM (SELECT m.CLIENTID + '|' + m.MTYPE + '|' + m.ENTITYID + '|' + m.TRUSTID + '|' + m.BRID AS csaId, LTRIM(RTRIM(m.CLIENTID)) AS companyCsaId, CASE m.MTYPE WHEN '13S' THEN 'secretary' WHEN '14D' THEN 'alternate' ELSE 'director' END AS role, CASE WHEN e.TYPE = 'C' THEN 'corporate' ELSE 'individual' END AS kind, COALESCE(NULLIF(LTRIM(RTRIM(CASE WHEN e.TYPE = 'C' THEN ISNULL(e.NAME_1, '') ELSE UPPER(ISNULL(e.NAME_1, '')) END + ' ' + ISNULL(e.NAME_2, ''))), ''), NULLIF(LTRIM(RTRIM(e.FORMNAME)), ''), NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), ''), 'Name not recorded in CSA') AS nameEn, NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), '') AS nameZh, COALESCE(STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_CE)), ''), ''), 1, 2, ''), STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_CE)), ''), ''), 1, 2, '')) AS correspondenceAddress, NULL AS email, CASE WHEN e.TYPE = 'C' THEN NULL ELSE NULLIF(LTRIM(RTRIM(e.IDNUM)), '') END AS idNumber, CASE WHEN e.TYPE = 'C' THEN COALESCE(sb.BUSREGNO, NULLIF(LTRIM(RTRIM(e.IDNUM)), '')) END AS brNumber, CASE WHEN e.TYPE = 'C' THEN NULLIF(LTRIM(RTRIM(e.TCSPNO)), '') END AS tcspLicence, CONVERT(char(10), m.SINCEDATE, 23) AS appointedOn, NULL AS ceasedOn FROM MASTER m JOIN CLIENT c ON c.CLIENTID = m.CLIENTID OUTER APPLY (SELECT TOP 1 x.TYPE, x.NAME_1, x.NAME_2, x.FORMNAME, x.NAME_1C, x.NAME_2C, x.IDNUM, x.TCSPNO, x.CLIENTID AS OWNCLIENT, x.REGADD_1E, x.REGADD_2E, x.REGADD_3E, x.REGADD_4E, x.REGADD_CE FROM ENTITY x WHERE x.ENTITYID = m.ENTITYID ORDER BY CASE WHEN x.SNUM = m.SNUM THEN 0 ELSE 1 END, x.SNUM DESC) e OUTER APPLY (SELECT TOP 1 r.BUSREGNO FROM BUSREG r WHERE NULLIF(LTRIM(RTRIM(e.OWNCLIENT)), '') IS NOT NULL AND r.CLIENTID = e.OWNCLIENT AND r.BRTYPE = 'COR' AND r.BUSREGNO LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' ORDER BY CASE WHEN r.TILLDATE IS NULL THEN 0 ELSE 1 END, r.ISRO DESC) sb WHERE m.MTYPE IN ('11D', '13S', '14D') AND m.TILLDATE IS NULL AND c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) q;

SELECT 'members' AS entity, COUNT(*) AS n, COUNT(*) - COUNT(DISTINCT q.csaId) AS duplicate_ids, SUM(CASE WHEN q.address IS NULL THEN 1 ELSE 0 END) AS missing_address, SUM(CASE WHEN q.className IS NULL THEN 1 ELSE 0 END) AS missing_className, SUM(CASE WHEN q.nameEn = 'Name not recorded in CSA' THEN 1 ELSE 0 END) AS no_name_in_csa FROM (SELECT s.CLIENTID + '|' + s.ENTITYID + '|' + s.TRUSTID + '|' + CAST(s.CLASSID AS varchar(10)) + '|' + s.REGIST AS csaId, LTRIM(RTRIM(s.CLIENTID)) AS companyCsaId, CASE WHEN e.TYPE = 'C' THEN 'corporate' ELSE 'individual' END AS kind, COALESCE(NULLIF(LTRIM(RTRIM(CASE WHEN e.TYPE = 'C' THEN ISNULL(e.NAME_1, '') ELSE UPPER(ISNULL(e.NAME_1, '')) END + ' ' + ISNULL(e.NAME_2, ''))), ''), NULLIF(LTRIM(RTRIM(e.FORMNAME)), ''), NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), ''), 'Name not recorded in CSA') AS nameEn, NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), '') AS nameZh, STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_CE)), ''), ''), 1, 2, '') AS address, COALESCE(NULLIF(LTRIM(RTRIM(k.DES)), ''), CASE WHEN k.ISORDINARY = 1 THEN 'Ordinary' ELSE 'Unnamed class' END) AS className, s.SHARES AS shares FROM MEMSHA s JOIN CLIENT c ON c.CLIENTID = s.CLIENTID JOIN CLISHA k ON k.CLIENTID = s.CLIENTID AND k.CLASSID = s.CLASSID AND k.ISACTIVE = 1 OUTER APPLY (SELECT TOP 1 x.TYPE, x.NAME_1, x.NAME_2, x.FORMNAME, x.NAME_1C, x.NAME_2C, x.IDNUM, x.REGADD_1E, x.REGADD_2E, x.REGADD_3E, x.REGADD_4E, x.REGADD_CE FROM ENTITY x WHERE x.ENTITYID = s.ENTITYID ORDER BY x.SNUM DESC) e WHERE s.MTYPE = '01M' AND s.SHARES > 0 AND c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) q;

SELECT 'shareClasses' AS entity, COUNT(*) AS n, COUNT(*) - COUNT(DISTINCT q.csaId) AS duplicate_ids, SUM(CASE WHEN q.className IS NULL THEN 1 ELSE 0 END) AS missing_className, SUM(CASE WHEN q.currency IS NULL THEN 1 ELSE 0 END) AS missing_currency FROM (SELECT k.CLIENTID + '|' + CAST(k.CLASSID AS varchar(10)) AS csaId, LTRIM(RTRIM(k.CLIENTID)) AS companyCsaId, COALESCE(NULLIF(LTRIM(RTRIM(k.DES)), ''), CASE WHEN k.ISORDINARY = 1 THEN 'Ordinary' ELSE 'Unnamed class' END) AS className, CASE WHEN LTRIM(RTRIM(ISNULL(k.CURRCODE, ''))) IN ('', 'HK$') THEN 'HKD' ELSE LTRIM(RTRIM(k.CURRCODE)) END AS currency, ISNULL(k.ISHARES, 0) AS issuedShares, ISNULL(k.REG_CASH, 0) + ISNULL(k.REG_ASSET, 0) + ISNULL(k.REG_INT, 0) AS totalAmount, ISNULL(k.PAID_CASH, 0) + ISNULL(k.PAID_ASSET, 0) + ISNULL(k.PAID_INT, 0) AS paidUp FROM CLISHA k JOIN CLIENT c ON c.CLIENTID = k.CLIENTID WHERE k.ISACTIVE = 1 AND k.ISHARES > 0 AND c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) q;

SELECT 'contacts' AS entity, COUNT(*) AS n, COUNT(*) - COUNT(DISTINCT q.csaId) AS duplicate_ids, SUM(CASE WHEN q.name IS NULL THEN 1 ELSE 0 END) AS missing_name, SUM(CASE WHEN q.email IS NULL THEN 1 ELSE 0 END) AS missing_email FROM (SELECT k.CLIENTID + '|' + CAST(k.CONIDX AS varchar(10)) AS csaId, LTRIM(RTRIM(k.CLIENTID)) AS companyCsaId, COALESCE(NULLIF(LTRIM(RTRIM(k.CONTACT)), ''), NULLIF(LTRIM(RTRIM(k.BEHALF)), ''), LTRIM(RTRIM(k.EMAIL))) AS name, LTRIM(RTRIM(k.EMAIL)) AS email, COALESCE(NULLIF(LTRIM(RTRIM(k.TEL)), ''), NULLIF(LTRIM(RTRIM(k.MOBILE)), '')) AS phone, CASE WHEN k.DOCLANG = 1 THEN 'tc' ELSE 'en' END AS language FROM CLICON k JOIN CLIENT c ON c.CLIENTID = k.CLIENTID WHERE NULLIF(LTRIM(RTRIM(k.EMAIL)), '') IS NOT NULL AND c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) q;

-- Officers by role and kind, and how many corporate secretaries have a registration number and a TCSP licence.
SELECT q.role, q.kind, COUNT(*) AS n, SUM(CASE WHEN q.brNumber IS NOT NULL THEN 1 ELSE 0 END) AS with_registration_no, SUM(CASE WHEN q.tcspLicence IS NOT NULL THEN 1 ELSE 0 END) AS with_tcsp_licence, SUM(CASE WHEN q.idNumber IS NOT NULL THEN 1 ELSE 0 END) AS with_id_number FROM (SELECT m.CLIENTID + '|' + m.MTYPE + '|' + m.ENTITYID + '|' + m.TRUSTID + '|' + m.BRID AS csaId, LTRIM(RTRIM(m.CLIENTID)) AS companyCsaId, CASE m.MTYPE WHEN '13S' THEN 'secretary' WHEN '14D' THEN 'alternate' ELSE 'director' END AS role, CASE WHEN e.TYPE = 'C' THEN 'corporate' ELSE 'individual' END AS kind, COALESCE(NULLIF(LTRIM(RTRIM(CASE WHEN e.TYPE = 'C' THEN ISNULL(e.NAME_1, '') ELSE UPPER(ISNULL(e.NAME_1, '')) END + ' ' + ISNULL(e.NAME_2, ''))), ''), NULLIF(LTRIM(RTRIM(e.FORMNAME)), ''), NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), ''), 'Name not recorded in CSA') AS nameEn, NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), '') AS nameZh, COALESCE(STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_CE)), ''), ''), 1, 2, ''), STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_CE)), ''), ''), 1, 2, '')) AS correspondenceAddress, NULL AS email, CASE WHEN e.TYPE = 'C' THEN NULL ELSE NULLIF(LTRIM(RTRIM(e.IDNUM)), '') END AS idNumber, CASE WHEN e.TYPE = 'C' THEN COALESCE(sb.BUSREGNO, NULLIF(LTRIM(RTRIM(e.IDNUM)), '')) END AS brNumber, CASE WHEN e.TYPE = 'C' THEN NULLIF(LTRIM(RTRIM(e.TCSPNO)), '') END AS tcspLicence, CONVERT(char(10), m.SINCEDATE, 23) AS appointedOn, NULL AS ceasedOn FROM MASTER m JOIN CLIENT c ON c.CLIENTID = m.CLIENTID OUTER APPLY (SELECT TOP 1 x.TYPE, x.NAME_1, x.NAME_2, x.FORMNAME, x.NAME_1C, x.NAME_2C, x.IDNUM, x.TCSPNO, x.CLIENTID AS OWNCLIENT, x.REGADD_1E, x.REGADD_2E, x.REGADD_3E, x.REGADD_4E, x.REGADD_CE FROM ENTITY x WHERE x.ENTITYID = m.ENTITYID ORDER BY CASE WHEN x.SNUM = m.SNUM THEN 0 ELSE 1 END, x.SNUM DESC) e OUTER APPLY (SELECT TOP 1 r.BUSREGNO FROM BUSREG r WHERE NULLIF(LTRIM(RTRIM(e.OWNCLIENT)), '') IS NOT NULL AND r.CLIENTID = e.OWNCLIENT AND r.BRTYPE = 'COR' AND r.BUSREGNO LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' ORDER BY CASE WHEN r.TILLDATE IS NULL THEN 0 ELSE 1 END, r.ISRO DESC) sb WHERE m.MTYPE IN ('11D', '13S', '14D') AND m.TILLDATE IS NULL AND c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) q GROUP BY q.role, q.kind ORDER BY n DESC;

-- Companies with no current director, or no secretary, in the mapped data.
SELECT SUM(CASE WHEN d.n IS NULL THEN 1 ELSE 0 END) AS no_director, SUM(CASE WHEN s.n IS NULL THEN 1 ELSE 0 END) AS no_secretary, COUNT(*) AS companies FROM (SELECT LTRIM(RTRIM(c.CLIENTID)) AS csaId, LTRIM(RTRIM(c.CLIENTID)) AS code, LTRIM(RTRIM(c.NAME_1 + ' ' + ISNULL(c.NAME_2, ''))) AS nameEn, NULLIF(LTRIM(RTRIM(c.NAME_C)), '') AS nameZh, b.BUSREGNO AS brNumber, NULLIF(LTRIM(RTRIM(c.COMNUM)), '') AS companyNumber, CONVERT(char(10), c.INCDATE, 23) AS incorporatedOn, NULL AS registeredOn, CASE WHEN c.AC_DDMM LIKE '[0-9][0-9]/[0-9][0-9]' THEN CAST(RIGHT(c.AC_DDMM, 2) AS int) END AS fyeMonth, CASE WHEN c.AC_DDMM LIKE '[0-9][0-9]/[0-9][0-9]' THEN CAST(LEFT(c.AC_DDMM, 2) AS int) END AS fyeDay, STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(c.REGADD_CE)), ''), ''), 1, 2, '') AS registeredOffice, 'private' AS companyType FROM CLIENT c OUTER APPLY (SELECT TOP 1 r.BUSREGNO FROM BUSREG r WHERE r.CLIENTID = c.CLIENTID AND r.BRTYPE = 'COR' AND r.TILLDATE IS NULL AND r.BUSREGNO LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' ORDER BY r.ISRO DESC) b WHERE c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) co LEFT JOIN (SELECT companyCsaId, COUNT(*) AS n FROM (SELECT m.CLIENTID + '|' + m.MTYPE + '|' + m.ENTITYID + '|' + m.TRUSTID + '|' + m.BRID AS csaId, LTRIM(RTRIM(m.CLIENTID)) AS companyCsaId, CASE m.MTYPE WHEN '13S' THEN 'secretary' WHEN '14D' THEN 'alternate' ELSE 'director' END AS role, CASE WHEN e.TYPE = 'C' THEN 'corporate' ELSE 'individual' END AS kind, COALESCE(NULLIF(LTRIM(RTRIM(CASE WHEN e.TYPE = 'C' THEN ISNULL(e.NAME_1, '') ELSE UPPER(ISNULL(e.NAME_1, '')) END + ' ' + ISNULL(e.NAME_2, ''))), ''), NULLIF(LTRIM(RTRIM(e.FORMNAME)), ''), NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), ''), 'Name not recorded in CSA') AS nameEn, NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), '') AS nameZh, COALESCE(STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_CE)), ''), ''), 1, 2, ''), STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_CE)), ''), ''), 1, 2, '')) AS correspondenceAddress, NULL AS email, CASE WHEN e.TYPE = 'C' THEN NULL ELSE NULLIF(LTRIM(RTRIM(e.IDNUM)), '') END AS idNumber, CASE WHEN e.TYPE = 'C' THEN COALESCE(sb.BUSREGNO, NULLIF(LTRIM(RTRIM(e.IDNUM)), '')) END AS brNumber, CASE WHEN e.TYPE = 'C' THEN NULLIF(LTRIM(RTRIM(e.TCSPNO)), '') END AS tcspLicence, CONVERT(char(10), m.SINCEDATE, 23) AS appointedOn, NULL AS ceasedOn FROM MASTER m JOIN CLIENT c ON c.CLIENTID = m.CLIENTID OUTER APPLY (SELECT TOP 1 x.TYPE, x.NAME_1, x.NAME_2, x.FORMNAME, x.NAME_1C, x.NAME_2C, x.IDNUM, x.TCSPNO, x.CLIENTID AS OWNCLIENT, x.REGADD_1E, x.REGADD_2E, x.REGADD_3E, x.REGADD_4E, x.REGADD_CE FROM ENTITY x WHERE x.ENTITYID = m.ENTITYID ORDER BY CASE WHEN x.SNUM = m.SNUM THEN 0 ELSE 1 END, x.SNUM DESC) e OUTER APPLY (SELECT TOP 1 r.BUSREGNO FROM BUSREG r WHERE NULLIF(LTRIM(RTRIM(e.OWNCLIENT)), '') IS NOT NULL AND r.CLIENTID = e.OWNCLIENT AND r.BRTYPE = 'COR' AND r.BUSREGNO LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' ORDER BY CASE WHEN r.TILLDATE IS NULL THEN 0 ELSE 1 END, r.ISRO DESC) sb WHERE m.MTYPE IN ('11D', '13S', '14D') AND m.TILLDATE IS NULL AND c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) o WHERE o.role <> 'secretary' GROUP BY companyCsaId) d ON d.companyCsaId = co.csaId LEFT JOIN (SELECT companyCsaId, COUNT(*) AS n FROM (SELECT m.CLIENTID + '|' + m.MTYPE + '|' + m.ENTITYID + '|' + m.TRUSTID + '|' + m.BRID AS csaId, LTRIM(RTRIM(m.CLIENTID)) AS companyCsaId, CASE m.MTYPE WHEN '13S' THEN 'secretary' WHEN '14D' THEN 'alternate' ELSE 'director' END AS role, CASE WHEN e.TYPE = 'C' THEN 'corporate' ELSE 'individual' END AS kind, COALESCE(NULLIF(LTRIM(RTRIM(CASE WHEN e.TYPE = 'C' THEN ISNULL(e.NAME_1, '') ELSE UPPER(ISNULL(e.NAME_1, '')) END + ' ' + ISNULL(e.NAME_2, ''))), ''), NULLIF(LTRIM(RTRIM(e.FORMNAME)), ''), NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), ''), 'Name not recorded in CSA') AS nameEn, NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), '') AS nameZh, COALESCE(STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(m.STAADD_CE)), ''), ''), 1, 2, ''), STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_CE)), ''), ''), 1, 2, '')) AS correspondenceAddress, NULL AS email, CASE WHEN e.TYPE = 'C' THEN NULL ELSE NULLIF(LTRIM(RTRIM(e.IDNUM)), '') END AS idNumber, CASE WHEN e.TYPE = 'C' THEN COALESCE(sb.BUSREGNO, NULLIF(LTRIM(RTRIM(e.IDNUM)), '')) END AS brNumber, CASE WHEN e.TYPE = 'C' THEN NULLIF(LTRIM(RTRIM(e.TCSPNO)), '') END AS tcspLicence, CONVERT(char(10), m.SINCEDATE, 23) AS appointedOn, NULL AS ceasedOn FROM MASTER m JOIN CLIENT c ON c.CLIENTID = m.CLIENTID OUTER APPLY (SELECT TOP 1 x.TYPE, x.NAME_1, x.NAME_2, x.FORMNAME, x.NAME_1C, x.NAME_2C, x.IDNUM, x.TCSPNO, x.CLIENTID AS OWNCLIENT, x.REGADD_1E, x.REGADD_2E, x.REGADD_3E, x.REGADD_4E, x.REGADD_CE FROM ENTITY x WHERE x.ENTITYID = m.ENTITYID ORDER BY CASE WHEN x.SNUM = m.SNUM THEN 0 ELSE 1 END, x.SNUM DESC) e OUTER APPLY (SELECT TOP 1 r.BUSREGNO FROM BUSREG r WHERE NULLIF(LTRIM(RTRIM(e.OWNCLIENT)), '') IS NOT NULL AND r.CLIENTID = e.OWNCLIENT AND r.BRTYPE = 'COR' AND r.BUSREGNO LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]' ORDER BY CASE WHEN r.TILLDATE IS NULL THEN 0 ELSE 1 END, r.ISRO DESC) sb WHERE m.MTYPE IN ('11D', '13S', '14D') AND m.TILLDATE IS NULL AND c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) o WHERE o.role = 'secretary' GROUP BY companyCsaId) s ON s.companyCsaId = co.csaId;

-- For each share class, do the members' shares add up to the issued shares? (The annual return is only generated when they do.)
SELECT SUM(CASE WHEN ISNULL(h.held, 0) = k.issuedShares THEN 1 ELSE 0 END) AS classes_matching, COUNT(*) AS classes, SUM(CASE WHEN k.totalAmount = k.paidUp THEN 1 ELSE 0 END) AS total_equals_paid FROM (SELECT k.CLIENTID + '|' + CAST(k.CLASSID AS varchar(10)) AS csaId, LTRIM(RTRIM(k.CLIENTID)) AS companyCsaId, COALESCE(NULLIF(LTRIM(RTRIM(k.DES)), ''), CASE WHEN k.ISORDINARY = 1 THEN 'Ordinary' ELSE 'Unnamed class' END) AS className, CASE WHEN LTRIM(RTRIM(ISNULL(k.CURRCODE, ''))) IN ('', 'HK$') THEN 'HKD' ELSE LTRIM(RTRIM(k.CURRCODE)) END AS currency, ISNULL(k.ISHARES, 0) AS issuedShares, ISNULL(k.REG_CASH, 0) + ISNULL(k.REG_ASSET, 0) + ISNULL(k.REG_INT, 0) AS totalAmount, ISNULL(k.PAID_CASH, 0) + ISNULL(k.PAID_ASSET, 0) + ISNULL(k.PAID_INT, 0) AS paidUp FROM CLISHA k JOIN CLIENT c ON c.CLIENTID = k.CLIENTID WHERE k.ISACTIVE = 1 AND k.ISHARES > 0 AND c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) k LEFT JOIN (SELECT companyCsaId, className, SUM(shares) AS held FROM (SELECT s.CLIENTID + '|' + s.ENTITYID + '|' + s.TRUSTID + '|' + CAST(s.CLASSID AS varchar(10)) + '|' + s.REGIST AS csaId, LTRIM(RTRIM(s.CLIENTID)) AS companyCsaId, CASE WHEN e.TYPE = 'C' THEN 'corporate' ELSE 'individual' END AS kind, COALESCE(NULLIF(LTRIM(RTRIM(CASE WHEN e.TYPE = 'C' THEN ISNULL(e.NAME_1, '') ELSE UPPER(ISNULL(e.NAME_1, '')) END + ' ' + ISNULL(e.NAME_2, ''))), ''), NULLIF(LTRIM(RTRIM(e.FORMNAME)), ''), NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), ''), 'Name not recorded in CSA') AS nameEn, NULLIF(LTRIM(RTRIM(ISNULL(e.NAME_1C, '') + ISNULL(e.NAME_2C, ''))), '') AS nameZh, STUFF('' + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_1E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_2E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_3E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_4E)), ''), '') + ISNULL(', ' + NULLIF(LTRIM(RTRIM(e.REGADD_CE)), ''), ''), 1, 2, '') AS address, COALESCE(NULLIF(LTRIM(RTRIM(k.DES)), ''), CASE WHEN k.ISORDINARY = 1 THEN 'Ordinary' ELSE 'Unnamed class' END) AS className, s.SHARES AS shares FROM MEMSHA s JOIN CLIENT c ON c.CLIENTID = s.CLIENTID JOIN CLISHA k ON k.CLIENTID = s.CLIENTID AND k.CLASSID = s.CLASSID AND k.ISACTIVE = 1 OUTER APPLY (SELECT TOP 1 x.TYPE, x.NAME_1, x.NAME_2, x.FORMNAME, x.NAME_1C, x.NAME_2C, x.IDNUM, x.REGADD_1E, x.REGADD_2E, x.REGADD_3E, x.REGADD_4E, x.REGADD_CE FROM ENTITY x WHERE x.ENTITYID = s.ENTITYID ORDER BY x.SNUM DESC) e WHERE s.MTYPE = '01M' AND s.SHARES > 0 AND c.JURISD = 'HKG' AND c.COMTYP = 'PVT' AND c.ISACTIVE = 1 AND c.COMSTA IN ('OPE', 'DOR')) x GROUP BY companyCsaId, className) h ON h.companyCsaId = k.companyCsaId AND h.className = k.className;
